using System.Text;
using Norse.Abstractions.Emit;
using Norse.Infrastructure.Web.Grpc.Generator.Shared;

namespace Norse.Infrastructure.Web.Server.Generator;

static class ServerComponentRegistrationEmitter
{
	internal static string Emit(string rootNamespace, ComponentDiscoveryResult result)
	{
		StringBuilder builder = new();
		builder.AppendCSharp(
			$$"""
			// <auto-generated/>
			namespace {{rootNamespace}};

			#pragma warning disable CS1591 // Generated registration: no XML doc comments.
			/// <summary>Generated by Norse.Infrastructure.Web.Server.Generator — compile-time validator, router, and Razor endpoint registration.</summary>
			public static class NorseServerComponentRegistration
			{
				/// <summary>Registers every discovered FluentValidation validator (idempotently) and the discovered routable component assemblies.</summary>
				public static global::Microsoft.Extensions.DependencyInjection.IServiceCollection AddNorseClientComponents(
					this global::Microsoft.Extensions.DependencyInjection.IServiceCollection services)
				{
			{{ValidatorRegistrations(result)}}
			{{RouteRegistration(rootNamespace, result)}}
					return services;
				}
			{{EndpointRegistration(result)}}
			}
			#pragma warning restore CS1591
			""");
		return builder.ToString();
	}

	// Comment printed once above the whole block, then one TryAddEnumerable call per discovered
	// validator -- the idempotent shape pairs with the client-side generator's identical registration
	// (Task 4), so both hosts converge on the same DI graph regardless of which one resolves a shared
	// validator first.
	static string ValidatorRegistrations(ComponentDiscoveryResult result) =>
		result.Validators.IsEmpty ?
			string.Empty :
			$"\t\t// validator (idempotent, pairs with the server-side generator's identical shape)\n{string.Join("\n", result.Validators.Select(ValidatorRegistration))}";

	static string ValidatorRegistration(ValidatorModel validator) =>
		$"\t\tglobal::Microsoft.Extensions.DependencyInjection.Extensions.ServiceCollectionDescriptorExtensions.TryAddEnumerable(\n\t\t\tservices, global::Microsoft.Extensions.DependencyInjection.ServiceDescriptor.Scoped(\n\t\t\t\ttypeof(global::FluentValidation.IValidator<{validator.RequestTypeName}>), typeof({validator.ValidatorTypeName})));";

	// Emitted only when Norse.Hosting.Web.Components.RoutesAdditionalAssemblies is resolvable --
	// non-Yggdrasil consumers get validators-only output. One AddSingleton call carrying every
	// discovered routable assembly marker, not one call per assembly: Blazor's Router takes a single
	// AdditionalAssemblies collection, so the registration mirrors that shape exactly. Same shape as
	// Task 4's client-side RouteRegistration -- the Router has no "implicit root" exception the way
	// MapRazorComponents<App> does, so the compilation's own routable marker (if any) stays in this
	// list even though EndpointRegistration below excludes it. When the own assembly's routes come
	// only from .razor pages, no page type is nameable here at all (the Razor generator shares this
	// pass), so this class itself stands in as that assembly's marker -- the registration only ever
	// reads typeof(...).Assembly, so any type in the assembly serves identically.
	static string RouteRegistration(string rootNamespace, ComponentDiscoveryResult result)
	{
		if (!result.RoutesAdditionalAssembliesTypeExists)
			return string.Empty;

		List<string> markers = [.. result.RoutableAssemblyMarkers];
		if (result.RequiresOwnAssemblyRouterEntry)
			markers.Add($"global::{rootNamespace}.NorseServerComponentRegistration");

		var joined = string.Join("\n", markers.Select(m => $"\t\t\t\ttypeof({m}).Assembly,"));
		return
			$"\t\t// router discovery\n\t\tglobal::Microsoft.Extensions.DependencyInjection.ServiceCollectionServiceExtensions.AddSingleton(\n\t\t\tservices, new global::Norse.Hosting.Web.Components.RoutesAdditionalAssemblies([\n{joined}\n\t\t\t]));";
	}

	// The endpoint half of composition -- distinct from RouteRegistration above in both mechanism
	// (RazorComponentsEndpointConventionBuilder.AddAdditionalAssemblies, not a Router singleton) and
	// exclusion rules: the Routes-holder assembly is included here (RouteRegistration excludes it,
	// since the Router's AppAssembly already covers it) but the compilation's own assembly is excluded
	// here (MapRazorComponents<App>'s implicit root already covers it -- RouteRegistration has no such
	// exception). That own-assembly exclusion has to reach the Routes-holder marker too: when
	// Norse.Hosting.Web.Components.Routes is declared in the compilation's own assembly (not a
	// referenced one), RoutesHolderIsOwnAssembly is true and the holder marker is the same
	// implicit-root case OwnAssemblyRoutableMarker exists to exclude -- including it unconditionally
	// would double it up with MapRazorComponents<App>'s own root. Gated on the same
	// RoutesAdditionalAssembliesTypeExists seam as RouteRegistration: the two mechanisms are
	// Yggdrasil's paired composition seam, on or off together.
	static string EndpointRegistration(ComponentDiscoveryResult result)
	{
		if (!result.RoutesAdditionalAssembliesTypeExists)
			return string.Empty;

		List<string> markers = [];
		if (result.RoutesHolderMarker is not null && !result.RoutesHolderIsOwnAssembly)
			markers.Add(result.RoutesHolderMarker);
		markers.AddRange(result.RoutableAssemblyMarkers.Where(m => m != result.OwnAssemblyRoutableMarker));

		var call = markers.Count == 0 ?
			"builder" :
			$"builder,\n{string.Join(",\n", markers.Select(m => $"\t\t\ttypeof({m}).Assembly"))}";

		return
			$"\t/// <summary>Feeds every discovered routable component assembly to Razor endpoint discovery — the render-mode half of discovery, distinct from the Router's.</summary>\n\tpublic static global::Microsoft.AspNetCore.Builder.RazorComponentsEndpointConventionBuilder AddNorseComponentAssemblies(\n\t\tthis global::Microsoft.AspNetCore.Builder.RazorComponentsEndpointConventionBuilder builder) =>\n\t\tglobal::Microsoft.AspNetCore.Builder.RazorComponentsEndpointConventionBuilderExtensions.AddAdditionalAssemblies({call});";
	}
}
